# pillar1_translations_part4.py - Handcrafted translations for DatingCharacterEvent items

TRANSLATIONS_CHAR_EVENTS = {
    # 103304 Amber - Bouncy Ball Showdown
    "DatingCharacterEvent.103304.1": "Bạn và Amber vừa nhìn thấy bàn Bóng Nảy là mắt hai người đã chạm nhau tóe lửa. Cả hai đều hiểu tỏng chuyện gì sắp diễn ra tiếp theo.\n\"Quyết đấu một trận phân cao thấp ngay tại đây nào!\" Bạn chộp lấy cây vợt rồi chỉ thẳng về phía cô nàng.\n\"Tôi... sẽ không thua đâu.\" Hiếm khi thấy Amber bộc lộ ý chí chiến đấu sục sôi đến thế.",
    "DatingCharacterEvent.103304.2": "\"Hây!\" \"Đỡ này!\" \"Á đù!\"\nTrận bóng diễn ra với nhịp độ nghẹt thở và kịch tính tột độ. Đôi bên ăn miếng trả miếng, bóng qua lại vun vút.\nTia lửa vô hình như bắn ra tung tóe khi hai người nhìn chằm chằm nhau qua mép bàn với sự kính nể dành cho thực lực đối phương.",
    "DatingCharacterEvent.103304.3": "Dù đã chiến đấu hết mình đầy quả cảm, rốt cuộc bạn vẫn đánh hụt bóng.\n\"Cô cừ thật đấy Amber, bái phục luôn.\"\n\"Đấu hay lắm, Boss.\"\nHai người cùng đặt vợt xuống bàn rồi bắt tay nhau cười sảng khoái. Quả là một trận thư hùng oanh liệt...\nTỉ số chung cuộc là 3 - 11.",
    "DatingCharacterEvent.103304.5": "Đại Chiến Bóng Nảy",
    "DatingCharacterEvent.103304.6": "Ghé thăm Khu Nghỉ Dưỡng Suối Nước Nóng để mở khóa",
    "DatingCharacterEvent.103304.7": "Bạn và Amber đã có một trận tỷ thí Bóng Nảy nảy lửa.\nKhông ngoài dự đoán, cô nàng đã cho bạn \"ăn hành\" ngập mặt.\nDẫu vậy, đây vẫn là một trận đấu mang lại vô vàn tiếng cười cho cả hai.",

    # 107303 Tilia - Hot Spring Endurance Training
    "DatingCharacterEvent.107303.1": "\"Ý hay đó nha! Tôi cũng đang muốn ngâm mình một chút đây.\" Tilia hào hứng đồng ý, nhưng rồi cô nàng lại co cẳng chạy thẳng về phía hành lý.\nLúc quay trở lại, trên tay cô nàng đang cầm chiếc mũ giáp Cận Vệ Hoàng Gia sáng loáng...",
    "DatingCharacterEvent.107303.2": "\"Đừng bảo là cô định...\"\n\"Chuẩn luôn! Đến lúc luyện tập sức chịu đựng rồi! Nếu chịu nổi bồn tắm nước sôi sùng sục, tôi sẽ không bao giờ ngất xỉu khi làm nhiệm vụ tuần tra nữa!\"\n\"Ờ thì... Đội mũ kim loại vào phòng xông hơi là rỉ sét hết trơn đấy cô nương ơi?\"",
    "DatingCharacterEvent.107303.3": "Nhân viên khu suối nước nóng lập tức dập tắt ngay ý tưởng tập luyện quái gở của Tilia. Được bạn dỗ dành thêm vài câu, cô nàng đành ngoan ngoãn tháo mũ ra.\n\"Đừng có lúc nào cũng căng như dây đàn thế chứ. Thư giãn đi nào.\"\n\"Xin lỗi nha... Oa, nước ấm áp dễ chịu quá đi mất. Cảm giác sướng ghê...\"\nTilia cuối cùng cũng trút bỏ được gánh nặng trong đầu và thoải mái tận hưởng làn nước ấm.",
    "DatingCharacterEvent.107303.6": "Ghé thăm Khu Nghỉ Dưỡng Suối Nước Nóng để mở khóa",
    "DatingCharacterEvent.107303.7": "Tilia từng nảy ra ý định đội cả mũ giáp vào ngâm suối nước nóng để \"luyện sức chịu đựng\" dở khóc dở cười.\nDĩ nhiên nhân viên tiệm chẳng đời nào cho phép trò đó.\nRốt cuộc, cả hai đã có một buổi ngâm mình thư giãn bình yên đúng nghĩa.",

    # 110303 Firenze - Romantic Stroll
    "DatingCharacterEvent.110303.1": "Khu chợ đông đúc nhộn nhịp hơn hẳn bạn tưởng tượng, vậy mà Firenze vẫn uyển chuyển lách qua dòng người một cách dễ dàng.\nĐối với một người suốt ngày ngồi bàn giấy, nàng thông thạo đường đi nước bước nơi này đến đáng ngạc nhiên.\nKhi bạn cất lời khen ngợi, nàng khẽ mỉm cười: \"Đó là lý do vì sao thị sát thực tế lại quan trọng đến vậy.\"",
    "DatingCharacterEvent.110303.2": "Hóa ra nàng thường xuyên rời văn phòng để đi khảo sát các trung tâm thương mại khắp thành phố, bao gồm cả khu chợ sầm uất này.\n\"Chỉ ở những nơi thế này, ta mới nhìn thấy rõ xu hướng thị trường chân thực và hơi thở đời sống dân sinh,\" nàng giải thích.\n\"Hóa ra với nàng, đây chỉ là công việc chứ chẳng phải đi dạo thảnh thơi...\" Bạn thở dài, quả đúng là phong cách của Firenze.\"",
    "DatingCharacterEvent.110303.3": "\"Bình thường thì là vậy. Nhưng hôm nay vì người đi cùng là cậu, nên ý nghĩa có lẽ sẽ đôi chút khác biệt đấy...\"\nFirenze nháy mắt đầy ẩn ý.\n...\nMột thoáng sau, nàng khẽ mỉm cười rồi tự nhiên luồn tay khoác lấy cánh tay bạn. Cả hai cùng sánh bước dạo quanh khu chợ tựa như bao cặp tình nhân bình dị khác.\n... Bạn thực sự chẳng thể nào đoán định nổi tâm tư của người phụ nữ này.",
    "DatingCharacterEvent.110303.5": "Chuyến Đi Dạo \"Lãng Mạn\"",
    "DatingCharacterEvent.110303.6": "Ghé thăm Khu Chợ để mở khóa",
    "DatingCharacterEvent.110303.7": "Firenze thông thạo khu chợ hơn bạn tưởng rất nhiều, bởi nàng thường xuyên đi thực địa nắm bắt tình hình buôn bán.\nBạn cứ ngỡ nàng lại bật chế độ cuồng công việc như mọi khi.\nThế nhưng nàng đã phá vỡ suy nghĩ đó bằng việc chủ động khoác tay bạn, biến chuyến thị sát khô khan thành buổi hẹn hò \"lãng mạn\" dạo phố... Bạn thật sự chẳng bao giờ đọc vị được nàng.",

    # 111304 Iris - Hot Spring Foggy Glass
    "DatingCharacterEvent.111304.1": "Vì cơ hội đến suối nước nóng rất hiếm hoi, bạn và Iris quyết định tận hưởng cho bằng hết.\n\"Em cảm thấy bao nhiêu mệt mỏi tan biến hết vào làn nước rồi nè... Đầu óc cứ bồng bềnh lơ lửng sao á...\"\n\"Ừ, thích thật đấy.\"\nHai người cùng tận hưởng không gian riêng tư bên bồn tắm của mình trong sự tĩnh lặng êm đềm.",
    "DatingCharacterEvent.111304.2": "Một lúc sau, tiếng sột soạt khe khẽ từ vách ngăn kính phía sau lưng phá tan bầu không khí im ắng.\nTò mò nổi lên, bạn bèn lên tiếng hỏi:\n\"Iris ơi, em đang làm trò gì bên đó thế?\"\n\"K-Không có gì đâu ạ!\"",
    "DatingCharacterEvent.111304.3": "Bị bạn gặng hỏi mãi, Iris đành ngượng ngùng thú nhận rằng em đang lấy ngón tay vẽ chữ lên mặt kính mờ hơi nước, tự thấy mình có hơi con nít.\n\"Thế rốt cuộc em viết chữ gì đấy?\"\n\"... Không có gì mà! Hơi nước làm nó tan biến mất tiêu rồi!\"",
    "DatingCharacterEvent.111304.6": "Ghé thăm Khu Nghỉ Dưỡng Suối Nước Nóng để mở khóa",
    "DatingCharacterEvent.111304.7": "Bạn và Iris đã có những phút giây ngâm mình thư thái tại suối nước nóng.\nBất chợt, bạn nghe thấy tiếng sột soạt bên kia vách ngăn: Cô bé đang hí hoáy viết chữ lên lớp sương mờ trên mặt kính.\nCho đến tận bây giờ, bạn vẫn chẳng thể nào biết được rốt cuộc hôm ấy em đã viết những lời gì.",

    # 112303 Noya - Jukebox Karaoke
    "DatingCharacterEvent.112303.1": "\"Tuyệt cú mèo luôn! Cả người sảng khoái hẳn ra!\"\nNoya vươn vai giơ hai tay lên trời thật cao. Cô nàng vừa định quay về xe Loxy ngủ một giấc thì một món Cổ Vật trong phòng chờ bỗng đập vào mắt.",
    "DatingCharacterEvent.112303.2": "\"Trông như máy phát nhạc tự động jukebox ấy nhỉ,\" bạn lên tiếng sau khi nhìn ngắm một hồi.\nThấy Noya có vẻ hiếu kỳ, bạn liền đưa micro cho cô nàng: \"Muốn thử hát một bài không?\"\nCô nàng run rẩy nhận lấy: \"A—A a! Oa, tiếng tớ vang to ghê ta!\"",
    "DatingCharacterEvent.112303.3": "\"♪... ♪♪... \"\nNoya nhanh chóng bị giai điệu cuốn đi say mê. Cô nàng ôm khư khư micro không chịu buông, vừa lắc lư theo điệu nhạc vừa hát hò say sưa quên cả đất trời.\nTrông cô nàng lúc này vừa buồn cười lại vừa đáng yêu hết sức.",
    "DatingCharacterEvent.112303.5": "Bữa Tiệc Hát Ca",
    "DatingCharacterEvent.112303.6": "Ghé thăm Khu Nghỉ Dưỡng Suối Nước Nóng để mở khóa",
    "DatingCharacterEvent.112303.7": "Sau khi tắm xong, bạn và Noya tình cờ thấy chiếc máy phát nhạc trong phòng nghỉ. Bạn khuyến khích cô nàng thử hát, và chẳng ngờ Noya lại phấn khích đến độ ôm micro hát liền tù tì một hơi.\nNhìn cô nàng vui vẻ rạng ngời như vậy, tâm trạng bạn cũng ấm áp lây.",

    # 118304 Coronis - Market Vase
    "DatingCharacterEvent.118304.1": "Rảo bước giữa khu chợ, đôi mắt của Coronis sáng lấp lánh như sao. Nàng dừng lại trước từng quầy hàng, săm soi từng món đồ với con mắt của một nhà nghiên cứu độc dược.",
    "DatingCharacterEvent.118304.2": "Hai người bước vào một tiệm hoa tươi.\n\"Nhìn hình dáng và chất liệu của chiếc bình hoa này xem. Cậu không thấy nó cực kỳ thích hợp để dùng làm bình thưng cất thuốc thử ma thuật sao?\"\nChủ tiệm hoa đứng bên cạnh nghe mà trố tròn mắt tái mặt.",
    "DatingCharacterEvent.118304.3": "Vì không muốn bị chủ tiệm đuổi cổ ra ngoài, bạn vội vã kéo cô nàng rời đi trước khi nàng kịp làm thí nghiệm tại chỗ.\nCoronis bĩu môi tiếc nuối: \"Người ta chỉ muốn tận dụng đồ tốt thôi mà...\"",
    "DatingCharacterEvent.118304.6": "Ghé thăm Khu Chợ để mở khóa",
    "DatingCharacterEvent.118304.7": "Coronis tìm thấy một chiếc bình hoa ở chợ và nằng nặc đòi mua về làm bình đựng thuốc độc dược.\nĐể cứu lấy thể diện và tránh bị chủ quán tống cổ, bạn đã phải hết lời can ngăn nhà nghiên cứu lập dị này.",

    # 130303 Donna - Lost Letter in Wind
    "DatingCharacterEvent.130303.1": "Một cơn gió núi bất ngờ ùa tới cuốn phăng lá thư trên tay Donna bay vút lên không trung rồi rơi xuống sườn núi dốc đứng.",
    "DatingCharacterEvent.130303.2": "\"Ôi không xong rồi!\"\nChẳng chút ngần ngại, Donna lao vụt theo hướng lá thư bay. Bạn hoảng hốt đuổi theo bén gót, tim đập thình thịch vì lo cho an toàn của cô bé.",
    "DatingCharacterEvent.130303.3": "\"A ha ha... Em không sao đâu, chỉ trượt chân xíu xiu thôi à.\"\nBạn tìm thấy Donna dưới một mỏm đá. Cô bé đang tươi cười giơ cao lá thư nguyên vẹn, dù đầu gối đã bị trầy xước một mảng.",
    "DatingCharacterEvent.130303.6": "Ghé thăm Vùng Đồi Núi để mở khóa",
    "DatingCharacterEvent.130303.7": "May mắn thay, Donna không bị thương nặng và lá thư cũng được thu hồi an toàn.\nNhìn cô bé ân cần phủi bụi cho bức thư chuyển phát của khách, bạn càng thêm trân trọng tinh thần trách nhiệm tuyệt vời của cô bưu tá nhỏ.",

    # 133303 Nazuka - Library Research
    "DatingCharacterEvent.133303.1": "Nazuka muốn tra cứu các tài liệu cổ xưa về môi trường sinh thái bên trong Cự Tháp. Hai người cùng nhau tới thư viện thành phố, nơi ngập tràn mùi giấy cũ thơm tho.",
    "DatingCharacterEvent.133303.2": "Cô nàng dẫn bạn sang một khu vực khác. Nhìn lên các giá sách chất cao chạm trần, bạn nhận ra toàn là những bộ tiểu thuyết phiêu lưu lãng mạn kỳ ảo.",
    "DatingCharacterEvent.133303.3": "Nazuka ôm chặt cuốn sách vào lòng. Như sực nhớ ra điều gì, cô nàng ngước đôi mắt long lanh lên hỏi bạn:\n\"Cậu có tin vào định mệnh giữa những người lữ khách không?\"",
    "DatingCharacterEvent.133303.5": "Thơ Tặng Cậu",
    "DatingCharacterEvent.133303.6": "Ghé thăm Thư Viện để mở khóa",
    "DatingCharacterEvent.133303.7": "Sau khi thu thập tài liệu quan trọng tại thư viện, Nazuka đã cho bạn thấy một góc tâm hồn thơ mộng khác của mình qua những trang tiểu thuyết lãng mạn.",

    # 134303 Fuyuka - Street Stroll & Milk
    "DatingCharacterEvent.134303.1": "Bạn và Fuyuka đang thong thả dạo bước trên con phố nhỏ.\n\"Sư phụ ơi, người có muốn mua thứ gì không ạ? Đệ tử xin được chiêu đãi!\"",
    "DatingCharacterEvent.134303.2": "Bạn chọn vài món đặc sản địa phương, và Fuyuka vui vẻ móc hầu bao thanh toán.\nNhưng đến lượt mình, cô bé lại tần ngần đứng trước quầy hàng một hồi lâu.",
    "DatingCharacterEvent.134303.3": "Fuyuka khẽ chỉ vào một hộp sữa tươi nhỏ nhắn.\n\"Chỉ lấy mỗi hộp sữa này thôi sao?\"\n\"D-Dạ vâng... Nghe bảo uống sữa này sẽ mau cao lớn ạ...\" Cô bé bẽn lẽn đỏ mặt đáp.",
    "DatingCharacterEvent.134303.6": "Ghé thăm Khu Phố để mở khóa",
    "DatingCharacterEvent.134303.7": "Fuyuka nhất quyết đòi chiêu đãi bạn đồ ăn vặt, nhưng bản thân cô bé lại chỉ ngượng ngùng chọn một hộp sữa tươi vì mong ước nhỏ nhoi muốn được cao thêm một chút.",

    # 142301 & 142303 Canace
    "DatingCharacterEvent.142301.6": "Ghé thăm Quán Ăn để mở khóa",
    "DatingCharacterEvent.142301.7": "Canace vô cùng ấn tượng trước sự am hiểu ẩm thực phong phú của bạn, hào hứng nghe bạn kể về những món ngon trên khắp đại lục.",
    "DatingCharacterEvent.142303.1": "Canace đang mải mê ngắm nhìn đàn cá bơi lội dưới làn nước trong vắt bên bờ suối. Bộ móng vuốt sắc nhọn của cô nàng thỉnh thoảng lại khẽ động đậy như bản năng của loài mèo săn mồi.",
    "DatingCharacterEvent.142303.2": "\"Cậu muốn thử bắt một con không?\"\nNghe bạn hỏi, Canace lắc đầu khe khẽ: \"Để chúng bơi lội tự do như vậy trông đẹp hơn nhiều.\"",
    "DatingCharacterEvent.142303.3": "Hai người cùng ngồi bên bờ đá, tận hưởng làn gió mát lành thổi qua mặt nước róc rách, cảm nhận sự an yên hiếm hoi giữa cuộc đời phiêu bạt.",
    "DatingCharacterEvent.142303.5": "Bên Dòng Suối Mát",
    "DatingCharacterEvent.142303.6": "Ghé thăm Bờ Suối để mở khóa",
    "DatingCharacterEvent.142303.7": "Một buổi chiều bình yên bên bờ suối cùng Canace, nơi cô nàng thú nhận rằng mình thích ngắm nhìn vẻ đẹp tự do của thiên nhiên hơn là săn bắt.",

    # 143303 Ann
    "DatingCharacterEvent.143303.1": "Ann hăm hở kéo tay bạn chạy một mạch đến bờ hồ lộng gió. Chú rồng nhỏ Coco cũng bay lượn vòng quanh hai người đầy phấn khích.",
    "DatingCharacterEvent.143303.2": "\"Ở đây gió mát nhất trần đời luôn!\" Ann dang rộng hai tay đón lấy luồng gió lồng lộng, tà áo bay phần phật trong nắng chiều.",
    "DatingCharacterEvent.143303.3": "Bạn mỉm cười ngồi xuống bãi cỏ ngắm nhìn cô bé cười đùa tung tăng, lòng bỗng thấy nhẹ nhõm như vừa trút bỏ được ngàn vạn âu lo.",
    "DatingCharacterEvent.143303.5": "Đón Gió Bên Hồ",
    "DatingCharacterEvent.143303.6": "Ghé thăm Bờ Hồ để mở khóa",
    "DatingCharacterEvent.143303.7": "Ann đã chia sẻ cho bạn địa điểm đón gió yêu thích nhất của mình, mang đến cho bạn một buổi chiều tràn ngập năng lượng và niềm vui trong trẻo.",

    # 144303 Freesia
    "DatingCharacterEvent.144303.1": "Freesia đang cẩn thận kiểm tra lại từng điều khoản trong hợp đồng ủy thác. Dù là lúc nghỉ ngơi, tác phong nghiêm túc chuẩn mực của nàng luật sư trẻ vẫn chẳng hề suy giảm.",
    "DatingCharacterEvent.144303.2": "\"Công việc quan trọng, nhưng sức khỏe và nụ cười của nàng cũng quan trọng không kém đâu đấy,\" bạn khẽ đẩy tách trà thơm về phía nàng.",
    "DatingCharacterEvent.144303.3": "Freesia khựng lại một nhịp, rồi khẽ nở nụ cười ngượng ngùng: \"Cảm ơn cậu... Đôi khi ở bên cậu, tôi mới nhớ ra mình cũng cần phải nghỉ ngơi.\"",
    "DatingCharacterEvent.144303.5": "Phút Thảnh Thơi Của Nàng Luật Sư",
    "DatingCharacterEvent.144303.6": "Ghé thăm Quán Trà để mở khóa",
    "DatingCharacterEvent.144303.7": "Bạn đã thành công thuyết phục Freesia tạm gác mớ hợp đồng khô khan sang một bên để cùng nhau nhâm nhi một tách trà thơm ấm lòng.",

    # 145302 & 145303 Flora / Otoha
    "DatingCharacterEvent.145302.1": "Bạn đứng tựa bên lan can cùng Otoha, làn gió biển mát rượi mơn man trên gương mặt. Khẽ nghiêng đầu nhìn sang, bạn thấy nàng đang phóng tầm mắt dõi về phía chân trời xa xăm ngoài bờ biển.\n\nBạn toan cất lời, nhưng vào giây phút cuối cùng, bạn lại chọn để sự tĩnh lặng êm đềm hòa cùng tiếng sóng biển miên man.",
    "DatingCharacterEvent.145302.6": "Ghé thăm Vườn Hoa để mở khóa",
    "DatingCharacterEvent.145302.7": "Cùng dạo bước giữa vườn hoa rực rỡ sắc màu, lắng nghe những tâm sự dịu dàng của thiếu nữ về ước mơ và hy vọng cho tương lai.",
    "DatingCharacterEvent.145303.1": "Otoha khẽ nâng chiếc dù hoa lên che nắng cho cả hai khi đi qua con đường rợp bóng cây phong đỏ rực.",
    "DatingCharacterEvent.145303.2": "\"Đi dạo dưới bóng râm thế này, cậu có thấy giống như hai chúng ta đang bước vào một thế giới bí mật không?\" Nàng khẽ nghiêng đầu hỏi bạn.",
    "DatingCharacterEvent.145303.3": "\"Miễn là có nàng ở đây, thế giới nào cũng đều là nơi tuyệt vời nhất,\" bạn đáp, khiến má nàng ửng hồng e thẹn.",
    "DatingCharacterEvent.145303.5": "Dưới Bóng Tán Dù Hoa",
    "DatingCharacterEvent.145303.6": "Ghé thăm Đường Rợp Bóng Cây để mở khóa",
    "DatingCharacterEvent.145303.7": "Chuyến đi dạo dưới chiếc dù hoa rợp bóng cùng Otoha đã để lại những rung động ngọt ngào và dịu êm khó phai.",

    # 150304 Minova
    "DatingCharacterEvent.150304.1": "Minova biểu diễn một cú lộn ván trượt điệu nghệ trên bờ kè đá rồi đáp đất chuẩn xác ngay trước mặt bạn.",
    "DatingCharacterEvent.150304.2": "\"Thế nào? Đỉnh chóp chưa?\" Cô nàng hất cằm cười đắc ý, mái tóc xõa tung bay trong gió đầy cá tính.",
    "DatingCharacterEvent.150304.3": "\"Điểm mười không có nhưng!\" Bạn giơ ngón tay cái tán thưởng, khiến thủ lĩnh Bang Tro Gió cười toe toét khoái chí.",
    "DatingCharacterEvent.150304.5": "Cú Lượn Đỉnh Cao Của Minova",
    "DatingCharacterEvent.150304.6": "Ghé thăm Công Viên Trượt Ván để mở khóa",
    "DatingCharacterEvent.150304.7": "Minova đã khoe cho bạn chiêu thức trượt ván mới toanh đầy phong cách, mang đến những tràng cười sảng khoái và tự do.",

    # 155303 Eleanor
    "DatingCharacterEvent.155303.1": "Eleanor đang say sưa ngắm nghía những cuốn kỳ thư ma pháp cổ xưa trên kệ sách bám bụi thời gian.",
    "DatingCharacterEvent.155303.2": "\"Những tri thức cổ đại này luôn ẩn chứa sức hấp dẫn ma mị đến lạ kỳ,\" nàng khẽ vuốt ve bìa sách da sờn rách.",
    "DatingCharacterEvent.155303.3": "\"Nhưng tri thức đẹp nhất hôm nay chính là nụ cười khi tìm thấy điều kỳ diệu của nàng đấy,\" bạn dịu dàng đáp lời.",
    "DatingCharacterEvent.155303.6": "Ghé thăm Phòng Lưu Trữ Cổ để mở khóa",
    "DatingCharacterEvent.155303.7": "Cùng Eleanor đắm mình trong biển tri thức ma pháp cổ xưa, chia sẻ những khoảnh khắc tĩnh lặng và sâu lắng bên nhau.",

    # 156301 Nazuna
    "DatingCharacterEvent.156301.3": "Chớp đúng thời cơ, bạn dứt khoát đập mạnh vào nút bấm tách một tiếng.\n\n\"Trúng rồi nè!\" Nazuna cũng đồng thời vỗ mạnh vào máy gắp thú, khiến chiếc càng gắp—bị chấn động làm chệch hướng—dĩ nhiên là gắp trượt vào không khí.\n\nNazuna cười nghiêng ngả gập cả người, nhưng sau đó cô nàng hào phóng tặng lại toàn bộ gấu bông mình vừa gắp được cho bạn.",
    "DatingCharacterEvent.156301.6": "Ghé thăm Khu Trò Chơi để mở khóa",
    "DatingCharacterEvent.156301.7": "Cùng Nazuna oanh tạc các máy gắp thú, chứng kiến tài thiện xạ và khả năng điều khiển gắp bách phát bách trúng của cô nàng.",

    # 158303 Chixia
    "DatingCharacterEvent.158303.1": "Chixia đang chăm chú chỉnh sửa lại khớp nối cơ học cho chú rối tinh xảo trên tay mình.",
    "DatingCharacterEvent.158303.2": "\"Mỗi cỗ máy đều có linh hồn riêng, chỉ cần cậu thật lòng lắng nghe nhịp thở của nó,\" nàng vừa tỉ mẩn vặn ốc vừa thầm thì.",
    "DatingCharacterEvent.158303.3": "Nhìn đôi bàn tay khéo léo của nàng thoăn thoắt làm việc dưới ánh nắng, bạn cảm nhận được niềm đam mê cháy bỏng của một người nghệ nhân chân chính.",
    "DatingCharacterEvent.158303.6": "Ghé thăm Xưởng Cơ Khí để mở khóa",
    "DatingCharacterEvent.158303.7": "Chixia đã cho bạn chiêm ngưỡng sự tinh xảo trong nghệ thuật chế tác cơ khí và thế giới nội tâm đầy chiều sâu của nàng.",

    # 159303 Cosette
    "DatingCharacterEvent.159303.1": "Cosette đang ngồi bên bàn thí nghiệm, ngắm nhìn những lọ dung dịch phát quang biến ảo muôn màu muôn vẻ.",
    "DatingCharacterEvent.159303.2": "\"Cậu có nghĩ phép màu thực sự tồn tại trong những giọt hóa chất này không?\" Nàng khẽ lắc nhẹ chiếc ống nghiệm.",
    "DatingCharacterEvent.159303.3": "\"Chắc chắn là có rồi, bằng chứng là nàng đã pha chế ra thứ phép thuật hớp hồn tôi rồi đấy thôi,\" bạn cười đáp.",
    "DatingCharacterEvent.159303.6": "Ghé thăm Phòng Thí Nghiệm để mở khóa",
    "DatingCharacterEvent.159303.7": "Một buổi chiều ngập tràn sắc màu huyền bí cùng Cosette bên những thí nghiệm ma dược độc đáo.",

    # 162301 & 162302 Alina Chess & Rainy Cabin
    "DatingCharacterEvent.162301.1": "Đám đông vây quanh bàn cờ hò reo cổ vũ nhiệt tình. Thấy thế, Alina cũng hào hứng xắn tay áo bước vào nghênh chiến.",
    "DatingCharacterEvent.162301.2": "Nhìn phong thái đĩnh đạc, ánh mắt tự tin ngút trời và từng nước cờ dứt khoát của cô nàng, ai nấy đều ngỡ như chiến thắng đã nắm chắc trong tay cô.",
    "DatingCharacterEvent.162301.3": "\"Chiếu tướng! Đổi bên nào!\"\nThế nhưng... Alina thua liền tù tì mười ván trắng bụng! Đối thủ của cô thậm chí còn nghi ngờ không biết cô nàng có đang cố tình nhường cờ hay không.",
    "DatingCharacterEvent.162301.4": "\"Không hề. Cậu đã chơi rất xuất sắc và xứng đáng với chiến thắng này.\" Alina đĩnh đạc đứng dậy bắt tay đối phương trong tiếng vỗ tay tán thưởng tinh thần thượng võ của khán giả.",
    "DatingCharacterEvent.162301.5": "Cô nàng bước chầm chậm về phía bạn, rời khỏi sàn đấu với phong thái tao nhã của một hiệp sĩ đích thực.\nNhưng chỉ có duy nhất bạn nhận ra bờ vai cô nàng đang run rẩy nhè nhẹ. Hóa ra cô nàng đang cay cú và ấm ức đến phát khóc vì trận thua thảm hại này!\nBạn nhẹ nhàng vỗ lưng an ủi cô nàng, trong lòng thầm tự hỏi: Tự tin ngút ngàn nhường ấy... Hóa ra cô nàng lại chơi cờ dở tệ đến mức này sao?",
    "DatingCharacterEvent.162301.6": "Ghé thăm Các Con Phố Của Filanis để mở khóa",
    "DatingCharacterEvent.162301.7": "Bị đám đông nhiệt tình lôi kéo, Alina tham gia vào trận đấu cờ. Thấy nàng tự tin ngút trời, bạn cứ ngỡ nàng là một kỳ thủ cừ khôi. Nào ngờ nàng thua trắng cả mười ván. Dù ngoài mặt vẫn giữ phong thái hiệp sĩ tao nhã, nhưng thực chất nàng lại đang ấm ức đến phát khóc khi trở về bên bạn.",

    "DatingCharacterEvent.162302.1": "Ngoài trời mưa rơi rả rích không ngớt, buộc bạn và Alina phải nán lại trong phòng trú mưa. Nhưng rồi một rắc rối phát sinh:\n\"Lulu lại quên gom chăn vào nhà nữa rồi...\"\nMấy chiếc chăn phơi sáng nay giờ đã ướt sũng nước mưa.",
    "DatingCharacterEvent.162302.2": "Trời đã về khuya. Bạn và Alina đành trải chăn hơ bên lò sưởi, hy vọng củi lửa sẽ hong khô chúng.\nĐể tránh bị cảm lạnh do nằm ngủ dưới sàn đất, bạn ngồi thức cùng cô nàng bên bếp lửa, trò chuyện linh tinh trên trời dưới biển cho đỡ buồn ngủ.\n\"Vùng sa mạc có cảnh sắc khác biệt lắm. Khi hoàng hôn buông xuống, cả thế gian tựa như được dát một lớp vàng rực rỡ...\"\n\"Và những người dân sống ở thành phố đó cũng có những quy tắc của riêng họ...\"",
    "DatingCharacterEvent.162302.3": "Càng chìm sâu vào dòng ký ức, cơn buồn ngủ càng ùa đến xâm chiếm lấy tâm trí bạn.\n\"... Rồi sau đó, mọi người ở viện mồ côi...\"\nKý ức của bạn dừng lại ở đó. Alina lặng lẽ lắng nghe, và khi thấy bạn đã ngủ say sưa, cô nàng liền khẽ khàng đứng dậy cởi áo khoác của mình ra.\n\"Cảm ơn cậu vì đã chia sẻ những câu chuyện ấy với tớ nhé.\"\nBạn cảm nhận được một luồng hơi ấm dịu dàng trùm lên người, xua tan đi cái lạnh buốt giá trong không gian.\n\"Giờ thì, hãy ngủ thật ngon nhé.\"",
    "DatingCharacterEvent.162302.7": "Vì Lulu quên cất chăn khiến chăn bị ướt mưa, bạn và Alina phải ngồi co ro bên lò sưởi qua đêm. Bạn cố gắng kể những câu chuyện quá khứ để thức cùng nàng, nhưng rồi lại thiếp đi lúc nào không hay. Trước khi chìm vào giấc ngủ say, bạn cảm nhận được hơi ấm dịu dàng từ chiếc áo khoác của nàng bao bọc lấy mình.",

    # 1807, 1907, 1908, 2007 Alina Special Events
    "DatingCharacterEvent.1807.1": "Một tràng náo nhiệt bất chợt thu hút sự chú ý của bạn. Nhìn qua, bạn thấy đám đông đang tụ tập quanh một bàn cờ thế.\nBạn liền ngỏ ý thách đấu một ván với Alina.",
    "DatingCharacterEvent.1807.2": "Giấu chiếc điện thoại dưới gầm bàn, bạn mở phần mềm cờ vua AI lên để nó mách nước từng nước cờ tối ưu nhất.\nChẳng có gì ngạc nhiên khi bạn thắng một mạch như chẻ tre.\n\"Đây là chiến thuật cao siêu phương nào thế này?\" Alina tròn mắt kinh ngạc hỏi.",
    "DatingCharacterEvent.1807.3": "Bạn thản nhiên đút điện thoại lại vào túi quần rồi mỉm cười đắc thắng: \"Chiến thuật của người có trí tuệ đấy.\"",

    "DatingCharacterEvent.1907.1": "Alina bảo bạn ngồi xuống để cô nàng thoa tinh dầu tắm cho. Bạn cởi áo ngoài ra và bất giác rùng mình vì làn không khí se se lạnh.",
    "DatingCharacterEvent.1907.2": "Cô nàng nhón lấy một chút tinh dầu hương hoa thơm ngát rồi cẩn thận xoa đều lên làn da bạn. Cô nàng ghé sát đến mức bạn có thể cảm nhận rõ hơi ấm từ cơ thể nàng đang phả nhẹ vào má mình.",
    "DatingCharacterEvent.1907.3": "Hơi ấm êm dịu, khẽ khàng ấy xua tan sạch sẽ cái lạnh thấu xương ra khỏi cơ thể bạn. Cảm giác ấm áp tựa như nàng vừa trao cho bạn một tia nắng ban mai, gợi nhớ về những ngày hè rực rỡ chan hòa.",

    "DatingCharacterEvent.1908.1": "Bạn bảo Alina nằm sấp xuống trong khi mình cầm lấy hộp tinh dầu tắm.\nLấy một lượng nhỏ ra lòng bàn tay, bạn nhỏ thêm vài giọt nước ấm, xoa hai bàn tay vào nhau cho tinh dầu phủ đều các đầu ngón tay.",
    "DatingCharacterEvent.1908.2": "Gạt nhẹ những lọn tóc vướng víu sang một bên, bạn thoa tinh dầu từ sau gáy miết dọc xuống sống lưng nàng rồi xoa đều ra hai bên. Bạn ấn lực sâu hơn một chút, đầu ngón tay cảm nhận rõ từng nhịp đập dịu dàng nơi huyết mạch của nàng.",
    "DatingCharacterEvent.1908.3": "Từng thớ cơ căng cứng dần được bạn khéo léo xoa dịu, làn da nàng thấm đượm tinh dầu trở nên mềm mại và ánh lên vẻ mịn màng. Mát-xa thế này đúng là tốn sức thật, bạn bất giác thấy người mình cũng nóng ran lên.",

    "DatingCharacterEvent.2007.1": "Đó là một đêm mưa lạnh buốt giá, hai người nép sát vào nhau tìm hơi ấm. Bạn khẽ nhắm mắt, để tâm trí trôi dạt miên man. Bạn rất muốn nói một điều gì đó, nhưng lời nghẹn lại nơi cuống họng, rồi nhẹ nhàng tan biến trước khi kịp cất thành lời...",
    "DatingCharacterEvent.2007.2": "Bạn chợt giật mình tỉnh giấc giữa đêm khuya thanh vắng. Thế giới bên ngoài khung cửa sổ chìm trong sắc lam thẫm u buồn nghẹt thở.\nAlina khe khẽ thì thào điều gì đó trong cơn mơ, và bạn nhẹ nhàng nằm xuống nép lại bên nàng.",
    "DatingCharacterEvent.2007.3": "Bướm vầng quang rực sắc hoàng kim.\nMộng ước lướt qua vì sao hình thập tự.\nNgay cả cánh chim phiêu bạt cũng chìm vào giấc say.",
}
